UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/CostaBrava.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
var sb = new System.Text.StringBuilder();
var garage = UnityEngine.Object.FindObjectOfType<VehicleGarage>();
if (garage == null) return "no garage";
for (int i = 0; i < garage.variants.Length; i++)
{
    if (garage.specIds[i] != "hdSportsCar") continue;
    garage.Apply(i);
    var v = garage.variants[i];
    // Find the body reference mesh and the bonnet mesh.
    Transform bodyMesh = null, bonnetMesh = null;
    foreach (Transform t in v.root.GetComponentsInChildren<Transform>())
    {
        if (t.name == "body_sports-car_0") bodyMesh = t;
        if (t.name == "body_bonnet.001") bonnetMesh = t;
    }
    if (bodyMesh == null || bonnetMesh == null) { sb.AppendLine("missing meshes"); break; }
    sb.AppendLine("body   localRot=" + bodyMesh.localRotation.eulerAngles.ToString("F2") + " parentLocalRot=" + bodyMesh.parent.localRotation.eulerAngles.ToString("F2"));
    sb.AppendLine("bonnet localRot=" + bonnetMesh.localRotation.eulerAngles.ToString("F2") + " parentLocalRot=" + bonnetMesh.parent.localRotation.eulerAngles.ToString("F2"));
    sb.AppendLine("body   parent localRot=" + bodyMesh.parent.localRotation.eulerAngles.ToString("F2") + " parentScale=" + bodyMesh.parent.localScale.ToString("F3"));
    sb.AppendLine("bonnet parent localRot=" + bonnetMesh.parent.localRotation.eulerAngles.ToString("F2") + " parentScale=" + bonnetMesh.parent.localScale.ToString("F3"));
    sb.AppendLine("bonnet parent worldRot=" + bonnetMesh.parent.rotation.eulerAngles.ToString("F2"));
    sb.AppendLine("body   parent worldRot=" + bodyMesh.parent.rotation.eulerAngles.ToString("F2"));
    sb.AppendLine("bonnet localPos=" + bonnetMesh.localPosition.ToString("F3") + " body localPos=" + bodyMesh.localPosition.ToString("F3"));
    break;
}
Debug.Log("PROBE13 " + sb.ToString().Replace("\r", "").Replace("\n", " || "));
return sb.ToString();
